Tool response:
Tool: create_supplier
Description: Create Supplier
Parameters:
    {
      "type": "object",
      "properties": {
        "name": {
          "type": "string",
          "title": "Name"
        },
        "email": {
          "type": "string",
          "title": "Email"
        },
        "phone": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "title": "Phone"
        },
        "address": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "title": "Address"
        },
        "payment_terms": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "title": "Payment Terms"
        },
        "currency": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "title": "Currency",
          "default": "USD"
        }
      },
      "required": [
        "name",
        "email"
      ]
    }

Tool response:
Tool: create_bom
Description: Create Bom
Parameters:
    {
      "type": "object",
      "properties": {
        "product_sku": {
          "type": "string",
          "title": "Product Sku"
        },
        "component_sku": {
          "type": "string",
          "title": "Component Sku"
        },
        "quantity": {
          "type": "number",
          "title": "Quantity"
        }
      },
      "required": [
        "product_sku",
        "component_sku",
        "quantity"
      ]
    }

Tool response:
Tool: create_purchase_order
Description: Create Purchase Order
Parameters:
    {
      "type": "object",
      "properties": {
        "supplier_id": {
          "type": "integer",
          "title": "Supplier Id"
        },
        "lines": {
          "items": {
            "properties": {
              "product_sku": {
                "type": "string",
                "title": "Product Sku"
              },
              "quantity": {
                "type": "integer",
                "title": "Quantity"
              },
              "unit_price": {
                "type": "number",
                "title": "Unit Price"
              }
            },
            "type": "object",
            "required": [
              "product_sku",
              "quantity",
              "unit_price"
            ],
            "title": "POLineCreate"
          },
          "type": "array",
          "title": "Lines"
        },
        "expected_delivery_date": {
          "type": "string",
          "title": "Expected Delivery Date"
        }
      },
      "required": [
        "supplier_id",
        "lines",
        "expected_delivery_date"
      ]
    }

Tool response:
Tool: create_product
Description: Create Product
Parameters:
    {
      "type": "object",
      "properties": {
        "sku": {
          "type": "string",
          "title": "Sku"
        },
        "name": {
          "type": "string",
          "title": "Name"
        },
        "description": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "title": "Description"
        },
        "product_type": {
          "type": "string",
          "title": "Product Type"
        }
      },
      "required": [
        "sku",
        "name",
        "product_type"
      ]
    }
